package ui_adapter.selector;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.AriaRole;
import ui_adapter.model.Selector;

public class SelectorResolver {

    /** Simple + reversible switch: pick first match on ambiguity to avoid strict-mode violations. */
    private static final boolean PICK_FIRST_ON_MULTIPLE = true;

    public Locator resolve(Page page, Selector selector) {
        if (selector == null) {
            return null;
        }

        Locator loc = resolveBaseStrategy(page, selector);

        // Optional refinement
        if (loc != null && selector.getNearText() != null && !selector.getNearText().isEmpty()) {
            loc = loc.filter(new Locator.FilterOptions().setHasText(selector.getNearText()));
        }

        if (PICK_FIRST_ON_MULTIPLE && loc != null) {
            loc = loc.first();
        }

        return loc;
    }

    private Locator resolveBaseStrategy(Page page, Selector selector) {
        String value = selector.getValue();
        if (value == null) value = "";

        switch (selector.getType()) {
            case TEST_ID:
                return page.getByTestId(value);

            case LABEL:
                return page.getByLabel(value);

            case PLACEHOLDER:
                return page.getByPlaceholder(value);

            case ROLE:
                // ROLE uses meta.role as AriaRole and value as accessible name
                String roleStr = selector.getRole();
                if (roleStr != null && !roleStr.isEmpty()) {
                    try {
                        AriaRole roleEnum = AriaRole.valueOf(roleStr.toUpperCase().replace(" ", "_"));
                        return page.getByRole(roleEnum, new Page.GetByRoleOptions().setName(value));
                    } catch (IllegalArgumentException ignore) {
                        // fall through to text
                    }
                }
                return page.getByText(value);

            case TEXT:
                // Prefer clickable elements when selecting by text.
                // Try: button with text, then link with text, then any element by text.
                Locator button = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(value));
                if (safeHasAny(button)) {
                    return button;
                }
                Locator link = page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName(value));
                if (safeHasAny(link)) {
                    return link;
                }
                return page.getByText(value);

            case CSS:
                return page.locator("css=" + value);

            case XPATH:
                return page.locator("xpath=" + value);

            default:
                return page.locator(value);
        }
    }

    private static boolean safeHasAny(Locator locator) {
        try {
            return locator != null && locator.count() > 0;
        } catch (Exception ignore) {
            return false;
        }
    }
}

package ui_adapter.adapter;

import ui_adapter.driver.BrowserDriver;
import ui_adapter.driver.PlaywrightDriver;
import ui_adapter.executor.ActionExecutor;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.TestRunResult;
import ui_adapter.selector.SelectorResolver;

import java.util.ArrayList;
import java.util.List;

public class UIActionAdapter {

    /**
     * Executes a list of UI actions sequentially using Playwright.
     * Stops execution on the first failure.
     *
     * @param actions The list of actions to execute.
     * @return TestRunResult containing the results of the execution.
     */
    public TestRunResult runActions(List<Action> actions) {
        if (actions == null || actions.isEmpty()) {
            return new TestRunResult(true, new ArrayList<>(), "No actions to execute");
        }

        // Using try-with-resources to ensure the driver is closed after execution
        try (BrowserDriver driver = new PlaywrightDriver()) {
            driver.start();

            SelectorResolver selectorResolver = new SelectorResolver();
            ActionExecutor executor = new ActionExecutor(driver, selectorResolver);

            List<ActionResult> stepResults = new ArrayList<>();
            boolean overallSuccess = true;
            String errorMessage = null;

            for (Action action : actions) {
                // Execute action
                ActionResult result = executor.execute(action);
                stepResults.add(result);

                // Check for failure
                if (result.getStatus() == ActionResult.Status.FAIL) {
                    overallSuccess = false;
                    errorMessage = "Execution stopped due to failure at step " + stepResults.size() + 
                                   ": " + result.getMessage();
                    break; // Stop execution on first FAILED action
                }
            }

            return new TestRunResult(overallSuccess, stepResults, errorMessage);

        } catch (Exception e) {
            // Handle critical errors during driver initialization or unexpected crashes
            e.printStackTrace();
            return new TestRunResult(false, new ArrayList<>(), "Critical Adapter Error: " + e.getMessage());
        }
    }
}

package ui_adapter.driver;

import com.microsoft.playwright.Page;

public interface BrowserDriver extends AutoCloseable {
    void start();
    Page getPage();
    void close();
    byte[] takeScreenshot();
}

package ui_adapter.driver;

import com.microsoft.playwright.*;

public class PlaywrightDriver implements BrowserDriver {
    private Playwright playwright;
    private Browser browser;
    private BrowserContext context;
    private Page page;

    @Override
    public void start() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(false));
        context = browser.newContext();
        page = context.newPage();
    }

    @Override
    public Page getPage() {
        if (page == null) {
            throw new IllegalStateException("Driver not started. Call start() first.");
        }
        return page;
    }

    @Override
    public byte[] takeScreenshot() {
        if (page == null) {
            return new byte[0];
        }
        return page.screenshot(new Page.ScreenshotOptions()
                .setFullPage(true));
    }

    @Override
    public void close() {
        if (context != null) {
            context.close();
        }
        if (browser != null) {
            browser.close();
        }
        if (playwright != null) {
            playwright.close();
        }
    }
}

package ui_adapter.error;

public enum ErrorType {
    TIMEOUT,
    ELEMENT_NOT_FOUND,
    ASSERTION_FAILED,
    NAVIGATION_FAILED,
    UNKNOWN_ERROR
}

package ui_adapter.executor;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.PlaywrightException;
import com.microsoft.playwright.TimeoutError;
import com.microsoft.playwright.options.WaitForSelectorState;
import ui_adapter.driver.BrowserDriver;
import ui_adapter.error.ErrorType;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.selector.SelectorResolver;

import java.nio.file.Paths;
import java.util.UUID;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;

public class ActionExecutor {
    private final BrowserDriver driver;
    private final SelectorResolver selectorResolver;

    public ActionExecutor(BrowserDriver driver, SelectorResolver selectorResolver) {
        this.driver = driver;
        this.selectorResolver = selectorResolver;
    }

    public ActionResult execute(Action action) {
        try {
            Page page = driver.getPage();
            // Selector might be null for actions like NAVIGATE (sometimes) or SCREENSHOT
            Locator locator = selectorResolver.resolve(page, action.getSelector());

            switch (action.getType()) {
                case NAVIGATE:
                    if (action.getValue() == null || action.getValue().isEmpty()) {
                        return ActionResult.fail("Navigation URL is missing", ErrorType.NAVIGATION_FAILED, null);
                    }
                    page.navigate(action.getValue());
                    return ActionResult.pass("Navigated to " + action.getValue());

                case CLICK:
                    locator.click();
                    return ActionResult.pass("Clicked element " + action.getSelector());

                case TYPE:
                    locator.fill(action.getValue());
                    return ActionResult.pass("Typed '" + action.getValue() + "' into " + action.getSelector());

                case WAIT_FOR_VISIBLE:
                    locator.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));
                    return ActionResult.pass("Element " + action.getSelector() + " is visible");

                case ASSERT_VISIBLE:
                    assertThat(locator).isVisible();
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " is visible");

                case ASSERT_TEXT:
                    assertThat(locator).containsText(action.getValue());
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " contains text '" + action.getValue() + "'");

                case SCREENSHOT:
                    String path = "screenshot-" + UUID.randomUUID() + ".png";
                    page.screenshot(new Page.ScreenshotOptions().setPath(Paths.get(path)));
                    return ActionResult.pass("Screenshot taken: " + path);

                default:
                     return ActionResult.fail("Unsupported action type: " + action.getType(), ErrorType.UNKNOWN_ERROR, null);
            }
        } catch (TimeoutError e) {
             return handleFailure(e, ErrorType.TIMEOUT, "Timeout executing " + action.getType());
        } catch (PlaywrightException e) {
             // Basic error mapping
             if (e.getMessage().contains("Target closed") || e.getMessage().contains("browser has been closed")) {
                 return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Browser closed unexpectedly");
             }
             if (e.getMessage().contains("NS_ERROR_UNKNOWN_HOST")) {
                 return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed: Unknown Host");
             }
             if (e.getMessage().contains("navigating to")) {
                 return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed");
             }
             if (e.getMessage().contains("Element is not attached to the DOM")) {
                 return handleFailure(e, ErrorType.ELEMENT_NOT_FOUND, "Element not found or detached");
             }
             return handleFailure(e, ErrorType.UNKNOWN_ERROR, e.getMessage());
        } catch (AssertionError e) {
             // Playwright assertions throw AssertionError on failure
             return handleFailure(new RuntimeException(e.getMessage()), ErrorType.ASSERTION_FAILED, "Assertion failed");
        } catch (Exception e) {
            return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Unexpected error: " + e.getMessage());
        }
    }

    private ActionResult handleFailure(Exception e, ErrorType type, String message) {
        String screenshotPath = null;
        try {
             // Attempt screenshot on failure
             screenshotPath = "failure-" + UUID.randomUUID() + ".png";
             if (driver != null) {
                 driver.getPage().screenshot(new Page.ScreenshotOptions().setPath(Paths.get(screenshotPath)));
             }
        } catch (Exception ignored) {
            // If screenshot fails (e.g. browser closed), we still want to return the original error
            screenshotPath = "screenshot-failed";
        }
        return ActionResult.fail(message + " | Cause: " + e.getMessage(), type, screenshotPath);
    }
}

