package ui_adapter.selector;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.AriaRole;
import ui_adapter.model.Selector;

public class SelectorResolver {

    public Locator resolve(Page page, Selector selector) {
        if (selector == null) {
            return null;
        }

        switch (selector.getType()) {
            case CSS:
                return page.locator("css=" + selector.getValue());
            case XPATH:
                return page.locator("xpath=" + selector.getValue());
            case TEXT:
                // matches text exactly or contains depending on exact flag, default loose in playwright locator string
                return page.locator("text=" + selector.getValue());
            case ROLE:
                // Role handling in Playwright usually requires an AriaRole enum.
                // We'll try to parse the string value to AriaRole, or fail if invalid.
                // Example value: "button", "link", etc.
                try {
                    AriaRole role = AriaRole.valueOf(selector.getValue().toUpperCase().replace(" ", "_"));
                    return page.getByRole(role);
                } catch (IllegalArgumentException e) {
                    throw new IllegalArgumentException("Invalid ARIA role: " + selector.getValue());
                }
            default:
                throw new UnsupportedOperationException("Selector type not supported: " + selector.getType());
        }
    }
}
